"""docs/WHY-BOXY.md: per model, every class that is still box-only / approximate / parametric (not true geometry) with counts and the reason recorded at conversion (ginfo.reason / source).
usage: tools/why_boxy.py [MODELDIR ...]   (default: newest converted dir of each reference model)"""
import sys, os, json, glob, sqlite3, collections
ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__))); CACHE = os.path.expanduser('~/.cache/rvt-viewer/models')
REF = [('residential-2020', '20_Residential_Sample_Project'), ('structural-2024', '43_Snowdon_Towers_Sample_Structural'), ('mep-2020', '23_rme_advanced_sample_project'),
       ('hvac-2024', '42_Snowdon_Towers_Sample_HVAC'), ('facades-2026', '58_Snowdon_Towers_Sample_Facades')]
EXPLAIN = {
    'matched': 'rebuilt from stored parameters; extents agree with Revit\'s bounding box, exact shape unproven',
    'param': 'rebuilt from stored parameters; extents do NOT agree with the stored box',
    'approx': 'a mesh exists but is incomplete / suspect (unsupported faces, wrong topology) or a rough rebuild',
    'bbox': 'no usable geometry: drawn as a box at the stored bounding box',
}
def newest(stem):
    ds = [d for d in glob.glob(os.path.join(CACHE, stem + '-*')) if os.path.exists(d + '/meta.json') and not d.endswith('.tmp')]
    return max(ds, key=lambda d: os.path.getmtime(d + '/meta.json')) if ds else None
def main(dirs):
    out = ['# Why does it still look boxy? (generated by tools/why_boxy.py)', '',
           'Per reference model: every class whose elements are not true geometry (decoded B-rep / saved-graphics mesh), with the count and the reason recorded during conversion. Analytical, reference, annotation and view-only categories are listed too when drawn as boxes (marked `hidden` when hidden by default).', '',
           '| fidelity | meaning |', '|---|---|'] + ['| %s | %s |' % kv for kv in EXPLAIN.items()] + ['']
    for name, d in dirs:
        m = json.load(open(d + '/meta.json')); hid = set(m.get('defaultHidden') or []); db = sqlite3.connect(d + '/model.sqlite')
        rows = db.execute("select e.fid, e.cls, e.cat, g.info from el e left join ginfo g on g.i = e.i where e.fid in ('bbox','approx','param','matched')").fetchall()
        tot = sum(1 for r in m['elements'] if r[6] not in ('none',) and r[2] and not r[7])
        agg = collections.defaultdict(lambda: [0, collections.Counter(), set()])
        for fid, cls, cat, info in rows:
            a = agg[(fid, cls)]; a[0] += 1; a[2].add(cat or '(none)')
            try: j = json.loads(info) if info else {}
            except Exception: j = {}
            fl = [f for f in (j.get('flags') or []) if f in ('unsupported_faces', 'mesh_topology_suspect', 'symbol_no_graphics', 'void')]
            a[1][(j.get('reason') or ((j.get('source') or '?') + (' [' + ', '.join(fl) + ']' if fl else '')))[:150]] += 1
        out += ['## %s  (%d drawn elements, %d not true geometry)' % (name, tot, sum(a[0] for a in agg.values())), '', '| fidelity | class | n | categories | reason(s) |', '|---|---|---|---|---|']
        for (fid, cls), a in sorted(agg.items(), key=lambda kv: (-kv[1][0], kv[0])):
            cats = ', '.join(sorted(a[2])[:3]) + (' hidden' if all(c in hid for c in a[2]) else '')
            out.append('| %s | %s | %d | %s | %s |' % (fid, cls, a[0], cats, '; '.join('%s (%d)' % (k, v) for k, v in a[1].most_common(3)).replace('|', '/')))
        out.append('')
    out += ['## Reasons in one place', '',
            '* **no saved graphics** (`symbol_no_graphics`, `no_saved_graphics`): the file stores no 3D tessellation for the element or its symbol (2D-only / annotation families, voids without cut body, reference points and hubs, rebar, MEP curves). Needs generative geometry from the reader (NEEDS-FROM-READER.md sections 3, 8).',
            '* **MEP curves** (ducts, pipes, conduit, cable tray, flex): drawn from the stored centre curve and section (parametric, extents match); the exact fittings/transitions are not decoded.',
            '* **mesh topology suspect**: curved faces (torus) whose triangles do not follow the surface (reader bug, NEEDS-FROM-READER.md section 10).',
            '* **unsupported faces** (`unsupported_faces`): faces the saved-graphics tessellation skipped; the viewer adds them through OpenCascade from `element_brep` when it can (ruled / revolution / hermite / bspline), otherwise the element stays approximate.',
            '* **structural framing/column profile families**: drawn from their saved graphics like any family instance; where Revit stores none the box remains (listed above per model).',
            '* **family instances in 2024-2026 files**: more symbols without saved graphics and more skipped faces than 2020 (see the reader table in docs/ACCEPTANCE-STATUS.md).']
    open(os.path.join(ROOT, 'docs', 'WHY-BOXY.md'), 'w').write('\n'.join(out) + '\n'); print('wrote docs/WHY-BOXY.md')
if __name__ == '__main__':
    dirs = [tuple(a.split('=', 1)) if '=' in a else (os.path.basename(a.rstrip('/')), a) for a in sys.argv[1:]] or [(n, newest(s)) for n, s in REF if newest(s)]
    main(dirs)
